import argparse
import hashlib
import pathlib
import sys

import pykwalify.core
import yaml

HEADER = """/* Autogenerated by cloud_config_gen.py from
 *     {}
 * DO NOT EDIT
 */

#include <stdint.h>
"""

CLOUD_CONFIG_SCHEMA_PATH = str(
    pathlib.Path(__file__).parent.parent.parent / "scripts" / "schemas" / "cloud-config-schema.yml"
)
with open(CLOUD_CONFIG_SCHEMA_PATH, encoding="utf-8") as f:
    cloud_config_schema = yaml.safe_load(f)


def cloud_load(path: str) -> dict:
    with open(path, encoding="utf-8") as f:
        cloud = yaml.safe_load(f)

    try:
        pykwalify.core.Core(source_data=cloud, schema_data=cloud_config_schema).validate()
    except pykwalify.errors.SchemaError as e:
        sys.exit(f"ERROR: Malformed cloud configuration file: {path}\n{e}")

    key = cloud["key"]
    if not isinstance(key, bytes):
        sys.exit(f"ERROR: Cloud public key in {path} must use the YAML !!binary type")
    if len(key) != 32:
        sys.exit(f"ERROR: Cloud public key in {path} must be exactly 32 bytes")
    return cloud


if __name__ == "__main__":
    parser = argparse.ArgumentParser(
        prog="cloud_config_gen",
        description="Convert a cloud description (public key and endpoint) to a header",
        allow_abbrev=False,
    )
    parser.add_argument("--config", type=str, required=True, help="Path to cloud configuration YAML file")
    parser.add_argument(
        "--default-config",
        type=str,
        required=True,
        help="Path to the default hosted cloud configuration YAML file",
    )
    args = parser.parse_args()

    cloud = cloud_load(args.config)
    key = cloud["key"]
    default_key = cloud_load(args.default_config)["key"]
    fingerprint = int.from_bytes(hashlib.sha256(key).digest()[:8], byteorder="big")
    default_fingerprint = int.from_bytes(hashlib.sha256(default_key).digest()[:8], byteorder="big")

    print(HEADER.format(args.config))
    print("/* First 64 bits of SHA-256, for build-time configuration selection only. */")
    print(f"#define INFUSE_CLOUD_PUBLIC_KEY_FINGERPRINT 0x{fingerprint:016X}ULL")
    print(f"#define INFUSE_CLOUD_PUBLIC_KEY_DEFAULT_FINGERPRINT 0x{default_fingerprint:016X}ULL")
    print("")
    print("/* Cloud server endpoint */")
    print(f'#define INFUSE_CLOUD_URL "{cloud["url"]}"')
    print(f"#define INFUSE_CLOUD_PORT {cloud['port']}")
    print("")
    print("#ifdef INFUSE_CLOUD_PUBLIC_KEY_DEFINE")
    print("static const uint8_t infuse_cloud_public_key[32] = {")
    for offset in range(0, len(key), 8):
        values = ", ".join(f"0x{byte:02x}" for byte in key[offset : offset + 8])
        print(f"\t{values},")
    print("};")
    print("#endif /* INFUSE_CLOUD_PUBLIC_KEY_DEFINE */")
